    protected:
        string marque;
        int vitesse;
    public:
        Vehicule(string m, int v) : marque(m), vitesse(v) {}
        void afficher() const {
            cout << marque << " a " << vitesse << " km/h" << endl;
        }
};

class Voiture : public Vehicule {
    private:
        int portes;
    public:
        Voiture(string m, int v, int p) : Vehicule(m, v), portes(p) {}
        void afficherDetails() const {
            afficher();
            cout << portes << " portes" << endl;
        }
};

int main() {
    string m;
    int v, p;
    cin >> m >> v >> p;
    Voiture voit(m, v, p);
    voit.afficherDetails();
    return 0;
}

