#include <iostream>
#include <vector>
using namespace std;

class Employe {
    protected:
        int salaireBase;
    public:
        Employe(int s) : salaireBase(s) {}
        virtual int salaire() const { return salaireBase; }
        virtual ~Employe() {}
};

class Manager : public Employe {
    private:
        int prime;
    public:
        Manager(int s, int p) : Employe(s), prime(p) {}
        int salaire() const override { return salaireBase + prime; }
};

int main() {
    vector<Employe*> equipe;
    equipe.push_back(new Employe(2000));
    equipe.push_back(new Manager(3000, 500));
    equipe.push_back(new Employe(2500));
    int total = 0;
    for (Employe* e : equipe) {
        total += e->salaire();
    }
    cout << "total = " << total << endl;
    for (Employe* e : equipe) {
        delete e;
    }
    return 0;
}

